try {
    const rawAnswer = $('HTTP Request: Dify Chat').item.json.answer || "";
    const baseData = $('When Executed by Another Workflow').first().json || {};
    // Безопасное извлечение ID: проверяем текущий ответ, затем контекст оркестратора
    const conversationId = $('HTTP Request: Dify Chat').item.json.conversation_id || (baseData.context && baseData.context.dify_conversation_id) || "unknown";

    // 1. ADVANCED CLEANUP: Вырезаем монолог <think> (DeepSeek/O1)
    let cleanText = rawAnswer.replace(/<think>[\s\S]*?<\/think>\n*/g, '').trim();

    // 2. SMART JSON EXTRACTION: Ищем только блок {...}, игнорируя вступительный текст ИИ
    let jsonString = cleanText;
    const jsonMatch = cleanText.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
        jsonString = jsonMatch[0];
    } else {
        // Fallback: если регулярка не сработала, чистим маркдаун
        jsonString = cleanText.replace(/```json/g, '').replace(/```/g, '').trim();
    }

    let parsedData = {};

    try {
        parsedData = JSON.parse(jsonString);
    } catch (error) {
        // ИЗОЛЯЦИЯ ПАДЕНИЙ (Graceful Degradation): 
        // Не "Авария ИИ", а мягкий перевод на инженера, чтобы клиент не пугался
        return [{
            json: {
                ...baseData,
                conversation_id: conversationId,
                parse_success: false,
                confidence_score: 0, 
                urgency: 10,
                category: "ESCALATION",
                draft_reply: "Система зафиксировала нестандартный ответ. Подключаю ведущего инженера к диалогу.",
                raw_ai_answer: rawAnswer // ВАЖНО: сохраняем бред ИИ для логов и разбора полетов
            }
        }];
    }

    // 3. СТРОГАЯ ТИПИЗАЦИЯ И НОРМАЛИЗАЦИЯ (Type Enforcement)
    // Гарантируем, что downstream узлы не упадут из-за NaN или undefined
    let confidence = parseInt(parsedData.confidence_score, 10);
    confidence = isNaN(confidence) ? 50 : Math.max(0, Math.min(100, confidence));

    let urgency = parseInt(parsedData.urgency, 10);
    urgency = isNaN(urgency) ? 5 : Math.max(1, Math.min(10, urgency)); // Зажимаем между 1 и 10

    let draftReply = String(parsedData.draft_reply || parsedData.answer || "").trim();
    let category = String(parsedData.category || "INFO").toUpperCase();

    // 4. ПРЕДОХРАНИТЕЛИ (Zero-Trust Policy)
    // Если ИИ говорит "Уверен на 100%", но выдал 3 слова — это галлюцинация.
    if (confidence >= 90 && draftReply.length < 15) {
        confidence = 30; // Искусственно занижаем, чтобы Оркестратор отдал это человеку
    }

    // 5. ВЫДАЧА ИДЕАЛЬНОГО КОНТРАКТА
    return [{
        json: {
            ...baseData, 
            conversation_id: conversationId,
            parse_success: true,
            confidence_score: confidence,
            urgency: urgency,
            category: category,
            draft_reply: draftReply
        }
    }];

} catch (error) {
    throw new Error(`[AI Parser Fatal Error]: Критический сбой обработки. Детали: ${error.message}`);
}

try {
    // 1. Берем данные прямо из триггера Оркестратора
    const triggerNode = $('When Executed by Another Workflow').first();
    if (!triggerNode) throw new Error("Нет входящих данных от Оркестратора");
    const baseData = triggerNode.json;

    // 2. Бронируем ID пользователя
    // contactId - чистый ID (например email) для запросов к БД
    const contactId = baseData.sender?.contact_id || "unknown_support_user";
    // safeUserId - экранированный ID для системного логгера Dify
    const safeUserId = String(contactId).replace(/[^a-zA-Z0-9_-]/g, '_');

    // 3. 🌟 ИНЪЕКЦИЯ КОНТЕКСТА: Работа с текстом и невидимыми файлами
    let rawText = baseData.payload?.raw_text || "";

    const hasFiles = baseData.payload?.has_attachments || (baseData.payload?.files_base64 && baseData.payload.files_base64.length > 0);

    if (hasFiles) {
        rawText = `[СИСТЕМНОЕ УВЕДОМЛЕНИЕ: Клиент прикрепил файл/скриншот. Строго следуй инструкции "ПЕРЕХВАТ МЕДИАФАЙЛОВ".]\n\nТекст клиента: ${rawText}`;
    }
    if (rawText.trim() === `[СИСТЕМНОЕ УВЕДОМЛЕНИЕ: Клиент прикрепил файл/скриншот. Строго следуй инструкции "ПЕРЕХВАТ МЕДИАФАЙЛОВ".]\n\nТекст клиента:`) {
        rawText += "Нет описания, только файл.";
    }

    // 4. Формируем контекст клиента
    const context = baseData.context || {};

    // 🌟 СТРОГАЯ ПРОВЕРКА СТАТУСА: Берем статус ИМЕННО из Оркестратора (leads_pipeline)
    let clientStatus = context.client_status;

    // Если Оркестратор почему-то не передал статус, ставим 'active' по умолчанию
    if (!clientStatus) {
        clientStatus = "active";
    }

    // 5. Собираем идеальный контракт для Dify
    let difyPayload = {
        "inputs": {
            "client_status": clientStatus,
            "project_brief": context.project_brief || "Бриф отсутствует",
            // 👇 КРИТИЧЕСКОЕ ДОБАВЛЕНИЕ: Передаем ID для Custom Tool (Агента)
            "contact_id": contactId 
        },
        "query": rawText,
        "response_mode": "blocking",
        "user": safeUserId
    };

    // 6. Прокидываем память (Conversation ID)
    if (context.dify_conversation_id) {
        difyPayload.conversation_id = context.dify_conversation_id;
    }

    return [{ json: difyPayload }];

} catch (error) {
    throw new Error(`[Dify Payload Builder Error]: ${error.message}`);
}

try {
    const kommoDomain = 'jikoyibo'; // Твой домен

    // 🌟 ENTERPRISE-ПАТТЕРН: Safe Data Fetcher
    function getSafeNodeJson(nodeName) {
        try {
            const item = $(nodeName).first();
            return item ? item.json : null;
        } catch (e) {
            return null; 
        }
    }

    const baseData = getSafeNodeJson('When Executed by Another Workflow') || {};

    // 🌟 БЕЗОПАСНЫЙ ПОИСК КАТЕГОРИИ (С учетом 'implementation')
    const aiDecision = getSafeNodeJson('Code: Parse AI Decision');
    // Если ИИ не работал, берем из Оркестратора, если и там нет - ставим 'IMPLEMENTATION'
    const category = aiDecision?.category || baseData.context?.category || 'IMPLEMENTATION';

    // 🌟 SMART TICKET LOCATOR
    const newTicketJson = getSafeNodeJson('DB: Create New Ticket');
    const existingTicketJson = getSafeNodeJson('Check Open Ticket');

    let ticketId = baseData.context?.active_ticket_id || "UNKNOWN";
    if (newTicketJson && newTicketJson.ticket_id) {
        ticketId = newTicketJson.ticket_id;
    } else if (existingTicketJson && existingTicketJson.ticket_id) {
        ticketId = existingTicketJson.ticket_id;
    }

    const crmId = baseData.context?.crm_deal_id || "0";

    function escapeHTML(str) {
        if (!str) return "<i>Текст отсутствует</i>";
        return String(str).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
    }

    const safeClientText = escapeHTML(baseData.payload?.raw_text);

    // 🌟 DYNAMIC HEADER (Динамические заголовки по категориям)
    const isNewTicket = !!newTicketJson;
    let header = "";

    if (isNewTicket) {
        let emoji = "🚨";
        let headerTitle = "НОВЫЙ ТИКЕТ";

        switch(category.toUpperCase()) {
            case 'ESCALATION': emoji = '🔥'; headerTitle = 'АВАРИЯ (КРИТИЧНО)'; break;
            case 'BUG': emoji = '🐛'; headerTitle = 'БАГ-РЕПОРТ'; break;
            case 'FEATURE_REQUEST': emoji = '💡'; headerTitle = 'ЗАПРОС НА ДОРАБОТКУ'; break;
            case 'IMPLEMENTATION': emoji = '🏗'; headerTitle = 'ЭТАП ВНЕДРЕНИЯ'; break;
        }
        header = `${emoji} <b>${headerTitle} #${ticketId}</b>\n`;
    } else {
        // Если тикет уже открыт, инженерам не нужно орать про аварию, это просто реплай
        header = `💬 <b>ОТВЕТ КЛИЕНТА (Тикет #${ticketId})</b>\n`;
    }

    const fullEngineerMessage = `${header}` +
                                `🏢 <b>CRM:</b> <a href="https://${kommoDomain}.kommo.com/leads/detail/${crmId}">Карточка клиента</a>\n` +
                                `👤 <b>От кого:</b> ${baseData.sender?.name || "Unknown"}\n\n` +
                                `📝 <b>ТЕКСТ:</b>\n${safeClientText}`;

    const base64Files = baseData.payload?.files_base64 || [];
    const results = [];

    // 1. Сначала отдаем все картинки (БЕЗ ТЕКСТА)
    if (Array.isArray(base64Files) && base64Files.length > 0) {
        for (let i = 0; i < base64Files.length; i++) {
            const fileObj = base64Files[i];
            if (!fileObj || !fileObj.base64) continue;
            try {
                const buffer = Buffer.from(fileObj.base64, 'base64');
                const binaryData = await this.helpers.prepareBinaryData(buffer, fileObj.file_name || `photo_${i}.jpg`, fileObj.mime_type || 'image/jpeg');
                results.push({
                    json: { 
                        type: "photo",
                        category: category,         // <-- ТЕПЕРЬ СВИТЧ УВИДИТ КАТЕГОРИЮ ФОТОГРАФИИ
                        is_new_ticket: isNewTicket, // <-- ТЕПЕРЬ СВИТЧ УВИДИТ, НОВЫЙ ЛИ ЭТО ТИКЕТ
                        ticket_id: ticketId         // <-- ПРОБРАСЫВАЕМ ID НА ВСЯКИЙ СЛУЧАЙ
                    },
                    binary: { data: binaryData }
                });
            } catch (e) {}
        }
    }

    // 2. Последним элементом отдаем ТЕКСТ С КНОПКАМИ (БЕЗ КАРТИНКИ)
    // (Этот блок остался без изменений, как ты и просил)
    results.push({
        json: {
            type: "text",
            ticket_id: ticketId,
            category: category, // <-- ПРОБРОСИЛИ КАТЕГОРИЮ ДЛЯ СВИТЧА
            engineer_message: fullEngineerMessage,
            is_new_ticket: isNewTicket 
        }
    });

    return results;

} catch (error) {
    throw new Error(`[Omni-Builder Error]: ${error.message}`);
}

